import{_ as t,o as d,c as o,a2 as r}from"./chunks/framework.BM5YPQmL.js";const p=JSON.parse('{"title":"Core reference","description":"Everything is exported by @pidrang/core, which depends only on @angular/core. Read libs/core/src/index.ts for the full list of re-exports.","frontmatter":{"description":"Everything is exported by @pidrang/core, which depends only on @angular/core. Read libs/core/src/index.ts for the full list of re-exports."},"headers":[],"relativePath":"reference/core.md","filePath":"reference/core.md"}'),c={name:"reference/core.md"};function a(i,e,n,s,l,u){return d(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="core-reference" tabindex="-1">Core reference <a class="header-anchor" href="#core-reference" aria-label="Permalink to &quot;Core reference&quot;">​</a></h1><p>Everything is exported by <code>@pidrang/core</code>, which depends only on <code>@angular/core</code>. Read <code>libs/core/src/index.ts</code> for the full list of re-exports.</p><h2 id="configuration" tabindex="-1">Configuration <a class="header-anchor" href="#configuration" aria-label="Permalink to &quot;Configuration&quot;">​</a></h2><p><code>providePidrang(config: PidrangConfig): EnvironmentProviders</code> registers three providers:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Required</th><th>What it does</th></tr></thead><tbody><tr><td><code>dataProvider</code></td><td><code>DataProvider</code></td><td>Yes</td><td>Register as <code>DATA_PROVIDER</code> token; every page reads through it. Source: <code>libs/core/src/lib/provide-pidrang.ts</code> lines 48–50.</td></tr><tr><td><code>resources</code></td><td><code>Resource[]</code></td><td>Yes</td><td>Register as <code>RESOURCES</code> token; pages read resource definitions from here. Source: same file, line 50.</td></tr><tr><td><code>authProvider</code></td><td><code>AuthProvider</code></td><td>No</td><td>When present, register as <code>AUTH_PROVIDER</code> token and provide <code>SESSION_IDENTITY</code> (a writable signal driven by <code>watchIdentity</code>). Without it, <code>injectAuthSession()</code> throws. Source: same file, lines 53–62, <code>watchIdentity</code> function at lines 23–45.</td></tr></tbody></table><h2 id="reading-the-configuration" tabindex="-1">Reading the configuration <a class="header-anchor" href="#reading-the-configuration" aria-label="Permalink to &quot;Reading the configuration&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Function</th><th>Returns</th><th>Throws when</th><th>Source</th></tr></thead><tbody><tr><td><code>injectDataProvider(): DataProvider</code></td><td>The configured <code>DataProvider</code>.</td><td>When <code>providePidrang()</code> was not called — Angular&#39;s DI error (no provider for <code>DATA_PROVIDER</code>).</td><td><code>libs/core/src/lib/inject-pidrang.ts</code> lines 8–9.</td></tr><tr><td><code>injectAuthProvider(): AuthProvider</code></td><td>The configured <code>AuthProvider</code>.</td><td>When no auth provider was passed to <code>providePidrang()</code>. Error message: <code>Pidrang: no auth provider configured, pass authProvider to providePidrang()</code>. Source: same file, lines 12–17.</td><td></td></tr><tr><td><code>injectResources(): Resource[]</code></td><td>The registered resources array.</td><td>When <code>providePidrang()</code> was not called — Angular&#39;s DI error (no provider for <code>RESOURCES</code>).</td><td>Same file, lines 20–21.</td></tr><tr><td><code>injectResource(name: string): Resource</code></td><td>The single resource matching <code>name</code>.</td><td>When no resource has that name. Error message: <code>Pidrang: no resource registered with name &quot;&lt;name&gt;&quot;</code>. Source: same file, lines 24–29.</td><td></td></tr></tbody></table><p>All functions use Angular&#39;s <code>inject()</code> and must be called in an injection context (component constructor, field initializer, factory).</p><h2 id="loading-a-list" tabindex="-1">Loading a list <a class="header-anchor" href="#loading-a-list" aria-label="Permalink to &quot;Loading a list&quot;">​</a></h2><p><code>injectResourceList&lt;T&gt;(resourceName: string \\| (() =&gt; string), params?: () =&gt; ListParams \\| undefined): ResourceRef&lt;ListResult&lt;T&gt; \\| undefined&gt;</code> wraps <code>DataProvider.getList</code> in Angular&#39;s native <code>resource()</code> API, returning a <code>ResourceRef</code> with the following members (documented under <code>ResourceRef</code> in <code>@angular/core</code>):</p><table tabindex="0"><thead><tr><th>Member</th><th>Type</th><th>What it holds</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>Signal&lt;ListResult&lt;T&gt; | undefined&gt;</code></td><td>The loaded result. <code>undefined</code> while loading, populated when done, kept across status changes.</td></tr><tr><td><code>status</code></td><td><code>Signal&lt;ResourceStatus&gt;</code></td><td><code>&#39;loading&#39;</code>, <code>&#39;reloading&#39;</code>, <code>&#39;error&#39;</code>, or <code>&#39;success&#39;</code>.</td></tr><tr><td><code>error</code></td><td><code>Signal&lt;Error | undefined&gt;</code></td><td>The error if status is <code>&#39;error&#39;</code>.</td></tr><tr><td><code>isLoading</code></td><td><code>Signal&lt;boolean&gt;</code></td><td>Shortcut for loading/reloading.</td></tr><tr><td><code>reload()</code></td><td><code>() =&gt; void</code></td><td>Triggers a new load.</td></tr></tbody></table><p>Two notes:</p><ul><li>The resource name may be a function (e.g. a route parameter signal); changing the return value reloads automatically.</li><li>When <code>params</code> returns <code>undefined</code>, loading is skipped entirely per <code>resource()</code>&#39;s own convention.</li></ul><p>Source: <code>libs/core/src/lib/resource-list.ts</code> lines 11–28.</p><h2 id="reading-the-session" tabindex="-1">Reading the session <a class="header-anchor" href="#reading-the-session" aria-label="Permalink to &quot;Reading the session&quot;">​</a></h2><p><code>injectAuthSession(): AuthSessionRef</code> — loads the identity once, subscribes to session change notifications and updates on its own after login/logout. It throws when no <code>authProvider</code> was passed to <code>providePidrang()</code>, because it calls <code>injectAuthProvider()</code> first.</p><table tabindex="0"><thead><tr><th>Member</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>value</code></td><td><code>Signal&lt;AuthIdentity | null | undefined&gt;</code></td><td><code>undefined</code> during initial load, <code>null</code> when signed out, <code>AuthIdentity</code> when signed in. Updates after each <code>login()</code>/<code>logout()</code>. Source: <code>libs/core/src/lib/auth-session.ts</code> lines 25–36 (<code>linkedSignal</code> computation).</td></tr><tr><td><code>error</code></td><td><code>Signal&lt;Error | undefined&gt;</code></td><td>Provider failure during load. Check this alongside <code>value</code>.</td></tr><tr><td><code>isLoading</code></td><td><code>Signal&lt;boolean&gt;</code></td><td>True between <code>reload()</code> calls until <code>getIdentity()</code> settles.</td></tr><tr><td><code>reload()</code></td><td><code>() =&gt; void</code></td><td>Force a reload of the identity. With <code>@pidrang/supabase</code> you do not need it after <code>login()</code>/<code>logout()</code>: the provider pushes the change through <code>onSessionChange</code>.</td></tr></tbody></table><p>Source: <code>libs/core/src/lib/auth-session-ref.ts</code> lines 5–10 (interface definition); <code>auth-session.ts</code> lines 16–51 (implementation).</p><h2 id="resource" tabindex="-1">Resource <a class="header-anchor" href="#resource" aria-label="Permalink to &quot;Resource&quot;">​</a></h2><p><code>interface Resource</code> describes one table as a resource:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>What it does</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td>—</td><td>Table name, resource name, and URL segment. Must not collide with existing routes. Source: <code>libs/core/src/lib/resource.ts</code> line 5.</td></tr><tr><td><code>label</code></td><td><code>string</code></td><td>Derived from <code>name</code></td><td>Display label for titles, menu items, headers. Generated from the table name by <code>readable-label.ts</code> in the CLI: split on <code>_</code>, <code>-</code>, <code>.</code>, case boundaries, capitalize first word, lowercase others.</td></tr><tr><td><code>fields</code></td><td><code>Field[]</code></td><td>—</td><td>Typed field definitions rendered by <code>ResourceForm</code> and <code>ResourceTable</code>. Source: same file, line 7.</td></tr><tr><td><code>defaultSorters</code></td><td><code>ListParams[&#39;sorters&#39;]</code></td><td><code>[ { field: &#39;id&#39;, order: &#39;asc&#39; } ]</code></td><td>Order applied when the page has no user-set sort. The CLI adds <code>{ field: &#39;created_at&#39;, order: &#39;desc&#39; }, { field: &#39;id&#39;, order: &#39;asc&#39; }</code> when a <code>timestamp</code> or <code>date</code> <code>created_at</code> column exists. Source: <code>libs/cli/src/lib/generate-resources-file.ts</code> lines 51–61. The <code>id</code> default itself comes from <code>libs/demo-shared/src/lib/resource-list-state.ts</code> line 96, copied into the generated helper <code>src/app/pidrang/resource-list-state.ts</code> at <code>libs/cli/src/lib/generated-pages.ts</code> line 72.</td></tr><tr><td><code>list</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Enable/disable the generic list page and its route. Source: <code>libs/core/src/lib/resource.ts</code> line 10.</td></tr><tr><td><code>create</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Enable/disable create. Source: same file, line 11.</td></tr><tr><td><code>show</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Enable/disable show. Source: same file, line 12.</td></tr><tr><td><code>edit</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Enable/disable edit. Source: same file, line 13.</td></tr><tr><td><code>delete</code></td><td><code>boolean</code></td><td><code>true</code></td><td>Enable/disable delete. Source: same file, line 14.</td></tr></tbody></table><p><code>isResourceActionEnabled(resource: Resource \\| undefined, action: ResourceAction): boolean</code> returns <code>false</code> when <code>resource</code> is <code>undefined</code> or <code>resource[action] === false</code>; <code>true</code> otherwise (enabled by default). Source: <code>libs/core/src/lib/is-resource-action-enabled.ts</code> lines 4–9.</p><h2 id="field" tabindex="-1">Field <a class="header-anchor" href="#field" aria-label="Permalink to &quot;Field&quot;">​</a></h2><p><code>interface Field</code> describes a single column:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Default</th><th>What it changes</th></tr></thead><tbody><tr><td><code>name</code></td><td><code>string</code></td><td>—</td><td>Column name, matches Supabase table column. Source: <code>libs/core/src/lib/field.ts</code> line 11.</td></tr><tr><td><code>label</code></td><td><code>string</code></td><td>Derived from <code>name</code></td><td>Header and form field label. Source: same file, line 12.</td></tr><tr><td><code>type</code></td><td><code>FieldType</code></td><td>—</td><td>Input type and validation pattern. Source: same file, line 13.</td></tr><tr><td><code>hidden</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Generic list/edit views skip the field at render time. Schema metadata, not baked into codegen. Source: same file, line 14. Per <code>docs/design-notes.md</code> line 25: <code>hidden</code> affects visibility only; <code>readOnly</code> prevents editing entirely.</td></tr><tr><td><code>readOnly</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Field excluded from create and edit forms entirely (primary keys, generated columns). Source: same file, line 15.</td></tr><tr><td><code>nullable</code></td><td><code>boolean</code></td><td><code>false</code></td><td>For <code>timestamp</code>, <code>time</code>, <code>numeric</code>, <code>date</code>: allows the field to be cleared (sent as <code>null</code>) rather than blocked as invalid when empty. Source: same file, line 16.</td></tr><tr><td><code>hasDefault</code></td><td><code>boolean</code></td><td><code>false</code></td><td>Shows hint &quot;Leave unchanged to use the database default.&quot; on create; exempts from required check while untouched. Source: same file, line 17.</td></tr></tbody></table><h2 id="field-types" tabindex="-1">Field types <a class="header-anchor" href="#field-types" aria-label="Permalink to &quot;Field types&quot;">​</a></h2><p><code>type FieldType = &#39;text&#39; | &#39;number&#39; | &#39;boolean&#39; | &#39;date&#39; | &#39;timestamp&#39; | &#39;time&#39; | &#39;numeric&#39;</code></p><table tabindex="0"><thead><tr><th>Type</th><th>Input</th><th>Kept as</th></tr></thead><tbody><tr><td><code>text</code></td><td><code>&lt;input type=&quot;text&quot;&gt;</code></td><td>String (always)</td></tr><tr><td><code>number</code></td><td><code>&lt;input type=&quot;number&quot;&gt;</code></td><td>Number (always)</td></tr><tr><td><code>boolean</code></td><td><code>&lt;mat-checkbox&gt;</code> / checkbox</td><td>Boolean (always)</td></tr><tr><td><code>date</code></td><td><code>&lt;input type=&quot;text&quot;&gt;</code> pattern <code>YYYY-MM-DD</code></td><td>String (never <code>Date</code>)</td></tr><tr><td><code>timestamp</code></td><td><code>&lt;input type=&quot;text&quot;&gt;</code> pattern ISO datetime</td><td>String (never <code>Date</code>)</td></tr><tr><td><code>time</code></td><td><code>&lt;input type=&quot;text&quot;&gt;</code> pattern HH:mm:ss</td><td>String (never <code>Date</code>)</td></tr><tr><td><code>numeric</code></td><td><code>&lt;input type=&quot;text&quot;&gt;</code> pattern decimal digits</td><td>String (never <code>Number</code>)</td></tr></tbody></table><p><code>date</code>, <code>timestamp</code>, <code>time</code> and <code>numeric</code> remain strings end to end so a calendar date, a zoned time, or a <code>bigint</code>/high-precision <code>numeric</code> round-trips without rounding through <code>JSON.parse</code> or <code>Date</code>. Validation uses regex patterns defined in <code>libs/core/src/lib/field-presentation.ts</code> lines 15–25.</p><p>Source: <code>libs/core/src/lib/field-presentation.ts</code> lines 3–48 (<code>INPUT_TYPE_BY_FIELD_TYPE</code>, <code>FORMAT_PATTERN_BY_FIELD_TYPE</code>, <code>TEXT_INPUT_BOUND_FIELD_TYPES</code>).</p><p>Five helpers turn a <code>Field</code> into what a form renders; both UI layers call them instead of keeping their own copy. <code>inputTypeForField(field): string</code> returns the <code>INPUT_TYPE_BY_FIELD_TYPE</code> lookup. <code>formatPatternForField(field): RegExp | undefined</code> returns the validation pattern for the type, <code>undefined</code> where there is none. <code>formatHintForField(field): string</code> returns the hint shown under the input. <code>fieldRequiresValueWhenEmpty(field): boolean</code> is true for <code>date</code>, <code>timestamp</code>, <code>time</code> and <code>numeric</code> when the field is not <code>nullable</code>. <code>isTextInputBoundField(field): boolean</code> is true when the type binds a plain text input. Source: same file, lines 50–70.</p><h2 id="list-params" tabindex="-1">List params <a class="header-anchor" href="#list-params" aria-label="Permalink to &quot;List params&quot;">​</a></h2><p><code>interface ListParams</code>:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>What it does</th></tr></thead><tbody><tr><td><code>pagination?.current</code></td><td><code>number</code></td><td>Page number (1-based).</td></tr><tr><td><code>pagination?.pageSize</code></td><td><code>number</code></td><td>Rows per page.</td></tr><tr><td><code>sorters?</code></td><td><code>{ field: string; order: &#39;asc&#39; | &#39;desc&#39; }[]</code></td><td>Sort fields and direction.</td></tr><tr><td><code>filters?</code></td><td><code>readonly Filter[] | Record&lt;string, FilterValue | null | undefined&gt;</code></td><td>AND-combined filters; shorthand object syntax maps values to <code>eq</code>. Values are normalized (<code>libs/core/src/lib/normalize-filters.ts</code>) and unsupported operators are rejected (<code>libs/core/src/lib/reject-unsupported-filters.ts</code>). Anything else is rejected before a request is sent.</td></tr></tbody></table><p>Three helpers apply those rules before any request. <code>normalizeFilters(filters: ListParams[&#39;filters&#39;]): Filter[]</code> returns <code>[]</code> for <code>undefined</code> or <code>null</code>, copies an array, turns the shorthand record into <code>{ field, operator: &#39;eq&#39;, value }</code> members (a <code>null</code> value becomes the <code>null</code> operator), and throws on a single filter object or a value that is not a plain object. <code>rejectUnsupportedFilters(filters, supported)</code> throws <code>Unsupported filter operator &quot;&lt;operator&gt;&quot; on field &quot;&lt;field&gt;&quot;</code> for an operator the backend cannot express. <code>validateListParams(params)</code> rejects a malformed page number, sorter or filter. Sources: <code>libs/core/src/lib/normalize-filters.ts</code> line 16, <code>libs/core/src/lib/reject-unsupported-filters.ts</code> lines 4–7, <code>libs/core/src/lib/validate-list-params.ts</code> line 83.</p><p><code>interface ListResult&lt;T&gt;</code>:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>What it holds</th></tr></thead><tbody><tr><td><code>data</code></td><td><code>T[]</code></td><td>The loaded rows.</td></tr><tr><td><code>total</code></td><td><code>number</code></td><td>Total row count for pagination. List parameters are validated before a request is sent (<code>validate-list-params.ts</code>). Source: same file, lines 22–25 (<code>ListResult</code>).</td></tr></tbody></table><p>Filter operators:</p><table tabindex="0"><thead><tr><th>Operator</th><th>Value type</th><th>Semantics</th></tr></thead><tbody><tr><td><code>eq</code></td><td><code>string | number | boolean</code></td><td>Equality. Shorthand <code>{ field: true }</code> is equivalent to <code>{ operator: &#39;eq&#39;, value: true }</code>.</td></tr><tr><td><code>ne</code></td><td><code>string | number | boolean</code></td><td>Inequality.</td></tr><tr><td><code>lt</code></td><td><code>string | number</code></td><td>Less than.</td></tr><tr><td><code>lte</code></td><td><code>string | number</code></td><td>Less than or equal.</td></tr><tr><td><code>gt</code></td><td><code>string | number</code></td><td>Greater than.</td></tr><tr><td><code>gte</code></td><td><code>string | number</code></td><td>Greater than or equal.</td></tr><tr><td><code>in</code></td><td><code>readonly FilterValue[]</code></td><td>Array membership.</td></tr><tr><td><code>contains</code></td><td><code>string</code></td><td>Case-insensitive substring (text columns only).</td></tr><tr><td><code>null</code></td><td><code>boolean</code></td><td>Checks for <code>NULL</code> values.</td></tr></tbody></table><p>Values accepted by operators: <code>string</code>, <code>number</code>, or <code>boolean</code> (<code>FilterValue</code>). Each operator enforces its own type at compile time through TypeScript constraints.</p><p>Source: <code>libs/core/src/lib/list-params.ts</code> lines 4–19 (<code>ListParams</code>), lines 22–25 (<code>ListResult</code>); <code>libs/core/src/lib/filter.ts</code> lines 1–11 (<code>Filter</code>); <code>libs/core/src/lib/filter-value.ts</code> line 1 (<code>FilterValue</code>); <code>libs/core/src/lib/filter-operator.ts</code> line 3 (<code>FilterOperator</code>). Exact semantics delegated to <a href="./../data-providers#filters">Writing a data provider</a>.</p><h2 id="data-provider" tabindex="-1">Data provider <a class="header-anchor" href="#data-provider" aria-label="Permalink to &quot;Data provider&quot;">​</a></h2><p><code>interface DataProvider</code>:</p><table tabindex="0"><thead><tr><th>Method</th><th>Parameters</th><th>Returns</th></tr></thead><tbody><tr><td><code>getList&lt;T&gt;(resource, params?)</code></td><td><code>resource: string</code>, <code>params?: ListParams</code></td><td><code>Promise&lt;ListResult&lt;T&gt;&gt;</code></td></tr><tr><td><code>getOne&lt;T&gt;(resource, params)</code></td><td><code>resource: string</code>, <code>params: GetOneParams</code></td><td><code>Promise&lt;T&gt;</code></td></tr><tr><td><code>create&lt;T&gt;(resource, params)</code></td><td><code>resource: string</code>, <code>params: CreateParams&lt;T&gt;</code></td><td><code>Promise&lt;T&gt;</code></td></tr><tr><td><code>update&lt;T&gt;(resource, params)</code></td><td><code>resource: string</code>, <code>params: UpdateParams&lt;T&gt;</code></td><td><code>Promise&lt;T&gt;</code></td></tr><tr><td><code>delete&lt;T&gt;(resource, params)</code></td><td><code>resource: string</code>, <code>params: DeleteParams</code></td><td><code>Promise&lt;T&gt;</code></td></tr></tbody></table><p>Each CRUD method beyond <code>getList</code> takes its own params object instead of positional arguments, so fields like <code>meta</code> can be added later without breaking signatures.</p><p>Source: <code>libs/core/src/lib/data-provider.ts</code> lines 4–13; <code>libs/core/src/lib/crud-params.ts</code> (all four param interfaces). See <a href="./../data-providers">Writing a data provider</a> for implementation details.</p><h2 id="authentication" tabindex="-1">Authentication <a class="header-anchor" href="#authentication" aria-label="Permalink to &quot;Authentication&quot;">​</a></h2><p><code>interface AuthProvider</code>:</p><table tabindex="0"><thead><tr><th>Member</th><th>Type</th><th>What it does</th></tr></thead><tbody><tr><td><code>login(params)</code></td><td><code>(params: LoginParams) =&gt; Promise&lt;void&gt;</code></td><td>Authenticates the user with <code>email</code> + <code>password</code>. On success the session signal updates automatically. Source: <code>libs/core/src/lib/auth-provider.ts</code> line 12.</td></tr><tr><td><code>logout()</code></td><td><code>() =&gt; Promise&lt;void&gt;</code></td><td>Signs out. Session becomes <code>null</code>. Source: same file, line 14.</td></tr><tr><td><code>getIdentity()</code></td><td><code>() =&gt; Promise&lt;AuthIdentity | null&gt;</code></td><td>Loads the current identity. Called once at startup and on each <code>reload()</code>. Source: same file, line 16.</td></tr><tr><td><code>onSessionChange?(listener)</code></td><td><code>(listener: () =&gt; void) =&gt; () =&gt; void</code></td><td>Optional subscription to session events. Returns an unsubscribe function. Source: same file, line 18.</td></tr></tbody></table><p><code>interface LoginParams</code>: <code>{ email: string; password: string }</code>. Source: <code>libs/core/src/lib/auth-provider.ts</code> lines 1–4.</p><p><code>interface AuthIdentity</code>: <code>{ id: string; email?: string }</code>. Source: same file, lines 6–9.</p><p>See <a href="./../authentication">Authentication and permissions</a> for a walkthrough.</p><h2 id="form-payloads" tabindex="-1">Form payloads <a class="header-anchor" href="#form-payloads" aria-label="Permalink to &quot;Form payloads&quot;">​</a></h2><p><code>ResourceForm</code> builds what it emits with these helpers; a hand-written form can use them too.</p><table tabindex="0"><thead><tr><th>Export</th><th>Signature</th><th>What it does</th></tr></thead><tbody><tr><td><code>ResourceFormMode</code></td><td><code>&#39;create&#39; | &#39;edit&#39;</code></td><td>The mode <code>ResourceForm</code> and <code>shouldBlockSubmit</code> switch on.</td></tr><tr><td><code>buildResourcePayload&lt;T&gt;</code></td><td><code>(mode: ResourceFormMode, fields: Field[], draft: T, isDirty: (name: string) =&gt; boolean): Record&lt;string, unknown&gt;</code></td><td>Keeps only the fields that changed (and are not <code>readOnly</code>), so the server&#39;s default applies to the rest.</td></tr><tr><td><code>shouldBlockSubmit</code></td><td><code>(mode: ResourceFormMode, dirty: boolean, invalid: boolean): boolean</code></td><td>Blocks an invalid create immediately; in edit it blocks only once the field is touched and invalid.</td></tr><tr><td><code>normalizeResourceValue&lt;T&gt;</code></td><td><code>(fields: Field[], value: T): T</code></td><td>Turns a record into the draft the form binds to.</td></tr></tbody></table><p>Source: <code>libs/core/src/lib/resource-form-payload.ts</code> lines 4, 34, 50 and 65. Where the components call them: <a href="./components">Components reference</a>.</p><h2 id="errors" tabindex="-1">Errors <a class="header-anchor" href="#errors" aria-label="Permalink to &quot;Errors&quot;">​</a></h2><p><code>class PidrangError extends Error</code>:</p><table tabindex="0"><thead><tr><th>Property</th><th>Type</th><th>Meaning</th></tr></thead><tbody><tr><td><code>category</code></td><td><code>PidrangErrorCategory</code></td><td>Classification for reactive handling. Source: <code>libs/core/src/lib/pidrang-error.ts</code> line 5.</td></tr><tr><td><code>code</code></td><td><code>string | undefined</code></td><td>Provider-specific error code (Supabase: PostgREST error code). Source: same file, line 6.</td></tr><tr><td><code>status</code></td><td><code>number | undefined</code></td><td>HTTP status if applicable. Source: same file, line 7.</td></tr><tr><td><code>cause</code></td><td><code>unknown</code></td><td>Underlying cause (original exception). Source: same file, line 8.</td></tr></tbody></table><p><code>type PidrangErrorCategory = &#39;unauthenticated&#39; | &#39;forbidden&#39; | &#39;not-found&#39; | &#39;unknown&#39;</code>. Source: <code>libs/core/src/lib/pidrang-error-category.ts</code> lines 1–6.</p><p>Each category maps to a user-facing response: <code>unauthenticated</code> → ask to sign in; <code>forbidden</code> → &quot;not allowed&quot;; <code>not-found</code> → record invisible or absent; <code>unknown</code> → generic message.</p><p>Source: <code>libs/core/src/lib/pidrang-error.ts</code> lines 4–17; <code>libs/core/src/lib/pidrang-error-options.ts</code> lines 3–8 (<code>PidrangErrorOptions</code> passed to the constructor); <code>libs/core/src/lib/pidrang-error-category.ts</code> lines 1–6. See <a href="./../data-providers#errors">Writing a data provider</a> for how providers construct these errors.</p><h3 id="tokens-and-identity" tabindex="-1">Tokens and identity <a class="header-anchor" href="#tokens-and-identity" aria-label="Permalink to &quot;Tokens and identity&quot;">​</a></h3><p>Three <code>InjectionToken</code>s are provided by <code>@pidrang/core</code>:</p><table tabindex="0"><thead><tr><th>Token</th><th>Type</th><th>Required</th><th>Description</th></tr></thead><tbody><tr><td><code>DATA_PROVIDER</code></td><td><code>InjectionToken&lt;DataProvider&gt;</code></td><td>Yes</td><td>Registered via <code>providePidrang({ dataProvider })</code>. Injected by <code>injectDataProvider()</code>. Source: <code>libs/core/src/lib/tokens.ts</code> line 7.</td></tr><tr><td><code>RESOURCES</code></td><td><code>InjectionToken&lt;Resource[]&gt;</code></td><td>Yes</td><td>Registered via <code>providePidrang({ resources })</code>. Injected by <code>injectResources()</code> / <code>injectResource()</code>. Source: same file, line 9.</td></tr><tr><td><code>AUTH_PROVIDER</code></td><td><code>InjectionToken&lt;AuthProvider&gt;</code></td><td>No</td><td>Optional — only registered when <code>authProvider</code> is passed to <code>providePidrang()</code>. Injected with <code>{ optional: true }</code>. Source: same file, line 11.</td></tr></tbody></table><p>When <code>authProvider</code> is configured, <code>SESSION_IDENTITY</code> is also provided: a <code>WritableSignal&lt;AuthIdentity | null&gt;</code> created by <code>watchIdentity</code>. It starts at <code>null</code>, refreshes once at startup and again on every <code>onSessionChange</code> notification, and keeps its last value when <code>getIdentity()</code> rejects. It is not the same signal as <code>injectAuthSession().value()</code>, which starts at <code>undefined</code> and becomes <code>undefined</code> on error. Source: <code>libs/core/src/lib/provide-pidrang.ts</code> lines 23-45 (<code>watchIdentity</code>), <code>libs/core/src/lib/session-identity.ts</code>, <code>libs/core/src/lib/auth-session.ts</code> lines 16-51.</p>',66)])])}const b=t(c,[["render",a]]);export{p as __pageData,b as default};
